// Modern Contemporary 10-marla in Johar Town: crisp white plaster, flamed grey granite portal,
// matte black aluminium frames, frameless glass railings, white marble reception floors and warm wood bedrooms.
s.structure({
  exterior_wall: { preset: "plaster_white", color: "#f4f3ef" },
  interior_wall: { preset: "paint", color: "#f3efe8" },
  ceiling: { preset: "paint", color: "#fbfaf7" },
  floors: {
    default: "porcelain_tile",
    drawing: "marble_white",
    lounge: "marble_white",
    stair: "marble_white",
    corridor: "marble_white",
    master_bedroom: "wood_floor_walnut",
    bedroom: "wood_floor_oak",
    dressing: "wood_floor_oak",
    kitchen: { preset: "porcelain_tile", color: "#dcd7ce" },
    dirty_kitchen: { preset: "ceramic_tile", color: "#cfc9be" },
    bath: "ceramic_tile",
    balcony: { preset: "porcelain_tile", color: "#b8b5ae" },
    terrace: { preset: "porcelain_tile", color: "#c2bdb4" },
    porch: { preset: "paving", color: "#7f8082" }
  },
  window_frame: "metal_black",
  door: "wood_walnut",
  glass: "glass_clear",
  railing: "glass",
  boundary_wall: { preset: "plaster_white", color: "#f0eee9" },
  gate: "metal_black",
  plinth: { preset: "stone_cladding", color: "#7d7f82" }
});

// Bold projecting flamed grey granite picture-frame portal across the first-floor front,
// with vertical walnut-toned aluminium fins on the left and a wood-lined soffit over the balcony.
const f1 = s.plan.levels.find((l) => l.id === "first");
const f1Bot = f1.elevation_ft;
const f1Top = f1.elevation_ft + f1.height_ft;

s.facade.frame({
  side: "front",
  from_x_ft: 3.8,
  to_x_ft: 30.0,
  from_h_ft: f1Bot - 0.6,
  to_h_ft: f1Top + 1.2,
  thickness_ft: 1.5,
  depth_ft: 2.2,
  material: { preset: "stone_cladding", color: "#8a8c8e", roughness: 0.75 }
});

s.facade.fins({
  side: "front",
  from_x_ft: 5.4,
  to_x_ft: 13.8,
  from_h_ft: f1Bot + 0.9,
  to_h_ft: f1Top - 0.3,
  count: 14,
  width_ft: 0.25,
  depth_ft: 0.65,
  material: { preset: "wood_walnut", color: "#5c4230" }
});

s.facade.canopy({
  rect: { x: 14.0, y: 8.2, w: 15.6, d: 5.8 },
  h_ft: f1Top - 0.1,
  thickness_ft: 0.6,
  material: { preset: "wood_walnut", color: "#5c4230" },
  downlights: true
});

s.facade.led_strip({
  side: "front",
  from_x_ft: 5.2,
  to_x_ft: 28.6,
  h_ft: f1Top - 0.35,
  color: "#ffd9a6"
});

// Ground floor grey granite accent piers between the drawing room windows, stepped white parapet band,
// and warm architectural wall washers.
const g = s.plan.levels.find((l) => l.id === "ground");
const f1 = s.plan.levels.find((l) => l.id === "first");
const gBot = g.elevation_ft;
const gTop = g.elevation_ft + g.height_ft;
const roofTop = f1.elevation_ft + f1.height_ft + 3.5;

s.facade.cladding({
  side: "front",
  from_x_ft: 4.6,
  to_x_ft: 7.4,
  from_h_ft: gBot,
  to_h_ft: gTop - 0.6,
  depth_ft: 0.25,
  material: { preset: "stone_cladding", color: "#8a8c8e" }
});

s.facade.cladding({
  side: "front",
  from_x_ft: 0.0,
  to_x_ft: 3.8,
  from_h_ft: gBot,
  to_h_ft: roofTop + 0.8,
  depth_ft: 0.2,
  material: { preset: "plaster_white", color: "#f7f6f2" }
});

s.facade.canopy({
  rect: { x: 0.0, y: 8.5, w: 17.0, d: 1.5 },
  h_ft: gTop - 0.2,
  thickness_ft: 0.7,
  material: { preset: "plaster_white", color: "#f4f3ef" },
  downlights: true
});

s.facade.wall_light({ side: "front", x_ft: 6.0, h_ft: 7.5, color: "#ffd9a8", intensity: 1.4 });
s.facade.wall_light({ side: "front", x_ft: 16.2, h_ft: 7.5, color: "#ffd9a8", intensity: 1.4 });
s.facade.wall_light({ side: "front", x_ft: 29.2, h_ft: 8.0, color: "#ffd9a8", intensity: 1.4 });

// Front boundary wall details matching the concept: horizontal timber-slat inset panel over a grey granite base,
// plus stone-clad gate piers with lantern caps.
const teak = s.mat({ preset: "wood_teak", color: "#7c4d2b" });
const granite = s.mat({ preset: "stone_cladding", color: "#858789" });
const metal = s.mat("metal_black");

const basePanel = new THREE.Mesh(new THREE.BoxGeometry(s.ft(10.5), s.ft(1.6), s.ft(0.14)), granite);
basePanel.position.copy(s.toWorld(9.8, -0.38, 1.1));
s.add(basePanel, { layer: "facade", kind: "boundary_wall:panel", label: "Granite boundary base" });

for (let i = 0; i < 5; i++) {
  const slat = new THREE.Mesh(new THREE.BoxGeometry(s.ft(10.5), s.ft(0.28), s.ft(0.12)), teak);
  slat.position.copy(s.toWorld(9.8, -0.38, 2.15 + i * 0.34));
  s.add(slat, { layer: "facade", kind: "boundary_wall:panel", label: "Teak boundary slat" });
}

for (const px of [15.2, 18.2, 28.8]) {
  const pier = new THREE.Mesh(new THREE.BoxGeometry(s.ft(1.2), s.ft(5.2), s.ft(1.1)), granite);
  pier.position.copy(s.toWorld(px, 0.0, 2.6));
  s.add(pier, { layer: "facade", kind: "boundary_wall:pier", label: "Granite gate pier" });

  const cap = new THREE.Mesh(new THREE.BoxGeometry(s.ft(0.7), s.ft(0.5), s.ft(0.7)), metal);
  cap.position.copy(s.toWorld(px, 0.0, 5.45));
  s.add(cap, { layer: "facade", kind: "boundary_wall:light", label: "Gate pier lantern" });
}

// Recessed false ceilings with warm perimeter coves and feature walls in the main reception rooms and bedrooms.
s.interior.false_ceiling({ room: "g_drawing", drop_ft: 0.75, inset_ft: 2.0, cove_color: "#ffd8a6" });
s.interior.downlights({ room: "g_drawing", rows: 2, cols: 3 });
s.interior.accent_wall({ room: "g_drawing", side: "left", material: "travertine" });

s.interior.false_ceiling({ room: "g_lounge", drop_ft: 0.75, inset_ft: 2.0, cove_color: "#ffd8a6" });
s.interior.downlights({ room: "g_lounge", rows: 2, cols: 4 });
s.interior.accent_wall({ room: "g_lounge", side: "front", material: { preset: "wood_walnut", color: "#5a3d2b" } });

s.interior.false_ceiling({ room: "g_bed1", drop_ft: 0.65, inset_ft: 1.6, cove_color: "#ffd8a6" });
s.interior.accent_wall({ room: "g_bed1", side: "left", material: { preset: "wood_oak", color: "#8c6947" } });

s.interior.false_ceiling({ room: "f_master", drop_ft: 0.7, inset_ft: 1.6, cove_color: "#ffd8a6" });
s.interior.downlights({ room: "f_master", rows: 2, cols: 2 });
s.interior.accent_wall({ room: "f_master", side: "left", material: { preset: "wood_walnut", color: "#543827" } });

s.interior.false_ceiling({ room: "f_lounge", drop_ft: 0.7, inset_ft: 2.0, cove_color: "#ffd8a6" });
s.interior.downlights({ room: "f_lounge", rows: 2, cols: 3 });
s.interior.accent_wall({ room: "f_lounge", side: "front", material: "travertine" });

// Single-car porch on the right: dark grey SUV parked in the bay, keeping the main door and drawing door clear.
s.furnish("car_suv", { room: "g_porch", at: [7.0, 9.0], color: "#3d3f42" });
s.furnish("plant_floor", { room: "g_porch", at: [11.8, 16.5] });

// Formal drawing room (17 x 18 ft): 3-seater sofa against the left travertine wall, 2-seater on the back wall,
// armchairs facing a marble coffee table, console on the right pier, and sheer curtains on the front window.
s.furnish("rug", { room: "g_drawing", at: [7.8, 9.5], size: { w_ft: 10.0, d_ft: 8.0 }, color: "#d4c8b8" });
s.furnish("sofa_3", { room: "g_drawing", against: "left", along_ft: 9.0, color: "#dcd3c6" });
s.furnish("side_table", { room: "g_drawing", against: "left", along_ft: 4.5 });
s.furnish("table_lamp", { room: "g_drawing", against: "left", along_ft: 4.5 });
s.furnish("painting", { room: "g_drawing", against: "left", along_ft: 9.0, size: { w_ft: 4.5, h_ft: 2.8 } });
s.furnish("sofa_2", { room: "g_drawing", against: "back", along_ft: 6.5, color: "#dcd3c6" });
