s.furnish("armchair", { room: "g_drawing", at: [11.5, 11.5], rot_deg: -75, color: "#7a4e32" });
s.furnish("coffee_table", { room: "g_drawing", at: [7.5, 9.5], size: { w_ft: 4.0, d_ft: 2.4 }, material: "marble_white", variant: "marble top" });
s.furnish("console_table", { room: "g_drawing", against: "right", along_ft: 14.0, size: { w_ft: 3.4, d_ft: 1.2 } });
s.furnish("mirror_wall", { room: "g_drawing", against: "right", along_ft: 14.0, size: { w_ft: 2.4, h_ft: 2.4 }, variant: "round" });
s.furnish("curtains", { room: "g_drawing", against: "front", along_ft: 5.5, size: { w_ft: 8.5 }, color: "#eae3d5" });
s.furnish("chandelier", { room: "g_drawing", at: [7.8, 9.5] });
s.furnish("ceiling_fan", { room: "g_drawing", at: [7.8, 9.5] });
s.furnish("ac_split", { room: "g_drawing", against: "left", along_ft: 14.0 });
s.furnish("plant_floor", { room: "g_drawing", at: [1.5, 1.5] });

// Ground TV lounge & dining (22 x 14.75 ft): L-sofa and coffee table in the central seating zone,
// 6-seater marble dining table on the right near the sliding door and open kitchen.
s.furnish("rug", { room: "g_lounge", at: [6.5, 7.5], size: { w_ft: 8.5, d_ft: 7.0 }, color: "#d5cdc0" });
s.furnish("sofa_l", { room: "g_lounge", at: [6.5, 5.2], rot_deg: 0, size: { w_ft: 8.0, d_ft: 5.5 }, color: "#b8afa0" });
