s.furnish("pendant", { room: "g_lounge", at: [16.5, 7.5], variant: "low" });
s.furnish("curtains", { room: "g_lounge", against: "right", along_ft: 7.5, size: { w_ft: 8.2 }, color: "#eae3d5" });
s.furnish("ceiling_fan", { room: "g_lounge", at: [6.5, 7.5] });
s.furnish("ac_split", { room: "g_lounge", against: "front", along_ft: 4.5 });
s.furnish("plant_floor", { room: "g_lounge", at: [20.5, 1.5] });

// Open kitchen (12 x 9.25 ft): L-shaped counter along the left and right walls, with sink, hob and fridge.
s.furnish("kitchen_counter", { room: "g_kitchen", against: "left", along_ft: 4.6, size: { w_ft: 7.5, d_ft: 2.0 } });
s.furnish("hob", { room: "g_kitchen", against: "left", along_ft: 4.6 });
s.furnish("kitchen_counter", { room: "g_kitchen", against: "right", along_ft: 4.6, size: { w_ft: 6.5, d_ft: 2.0 } });
s.furnish("sink_kitchen", { room: "g_kitchen", against: "right", along_ft: 4.6 });
s.furnish("fridge", { room: "g_kitchen", against: "back", along_ft: 9.5 });
s.furnish("water_dispenser", { room: "g_kitchen", against: "back", along_ft: 1.5 });

// Enclosed dirty kitchen / utility room (12 x 6 ft) at the back: secondary cooking run, sink and washing machine.
s.furnish("kitchen_counter", { room: "g_dirty", against: "left", along_ft: 3.0, size: { w_ft: 5.0, d_ft: 2.0 } });
s.furnish("hob", { room: "g_dirty", against: "left", along_ft: 3.0 });
s.furnish("sink_kitchen", { room: "g_dirty", against: "back", along_ft: 6.0 });
s.furnish("washing_machine", { room: "g_dirty", against: "front", along_ft: 2.5 });

// Parents' ground-floor bedroom (12 x 15.25 ft): queen bed on the left wall, wardrobe on the front wall,
// TV on the right wall, keeping a clear path from the lounge door to the attached bath door.
s.furnish("bed_queen", { room: "g_bed1", against: "left", along_ft: 7.5, color: "#cfc6b8", variant: "upholstered headboard" });
s.furnish("side_table", { room: "g_bed1", against: "left", along_ft: 3.8 });
s.furnish("side_table", { room: "g_bed1", against: "left", along_ft: 11.2 });
s.furnish("table_lamp", { room: "g_bed1", against: "left", along_ft: 3.8 });
s.furnish("table_lamp", { room: "g_bed1", against: "left", along_ft: 11.2 });
s.furnish("rug", { room: "g_bed1", at: [5.5, 7.5], size: { w_ft: 7.5, d_ft: 6.5 }, color: "#dfd7ca" });
s.furnish("wardrobe", { room: "g_bed1", against: "front", along_ft: 8.5, size: { w_ft: 5.0, d_ft: 2.0 } });
s.furnish("tv_unit", { room: "g_bed1", against: "right", along_ft: 10.5, size: { w_ft: 4.2, d_ft: 1.3 } });
s.furnish("tv", { room: "g_bed1", against: "right", along_ft: 10.5, size: { w_ft: 3.4 } });
s.furnish("prayer_mat", { room: "g_bed1", at: [3.0, 13.0], rot_deg: -90 });
s.furnish("curtains", { room: "g_bed1", against: "back", along_ft: 6.0, size: { w_ft: 6.5 }, color: "#ece5d8" });
s.furnish("ceiling_fan", { room: "g_bed1", at: [6.0, 7.5] });
s.furnish("ac_split", { room: "g_bed1", against: "left", along_ft: 7.5 });

// Parents' attached bathroom (6 x 15.25 ft): vanity, WC and walk-in shower at the back.
s.furnish("vanity", { room: "g_bath1", against: "right", along_ft: 11.5, size: { w_ft: 3.2 } });
s.furnish("mirror_wall", { room: "g_bath1", against: "right", along_ft: 11.5, size: { w_ft: 2.8, h_ft: 3.0 } });
s.furnish("wc", { room: "g_bath1", against: "right", along_ft: 7.0 });
s.furnish("shower", { room: "g_bath1", against: "back", along_ft: 3.0 });
s.furnish("towel_rail", { room: "g_bath1", against: "left", along_ft: 4.0 });

// First-floor master bedroom (10 x 14 ft): queen bed on the solid left walnut wall, TV on the right pier
// between the bath door and dressing arch, curtains on the front balcony sliding door.
s.furnish("bed_queen", { room: "f_master", against: "left", along_ft: 7.2, color: "#cbc2b4", variant: "upholstered headboard" });
s.furnish("side_table", { room: "f_master", against: "left", along_ft: 3.6 });
s.furnish("side_table", { room: "f_master", against: "left", along_ft: 10.8 });
s.furnish("table_lamp", { room: "f_master", against: "left", along_ft: 3.6 });
s.furnish("table_lamp", { room: "f_master", against: "left", along_ft: 10.8 });
s.furnish("rug", { room: "f_master", at: [5.0, 7.2], size: { w_ft: 7.0, d_ft: 6.5 }, color: "#ded6c8" });
s.furnish("tv_unit", { room: "f_master", against: "right", along_ft: 7.0, size: { w_ft: 4.0, d_ft: 1.2 } });
s.furnish("tv", { room: "f_master", against: "right", along_ft: 7.0, size: { w_ft: 3.4 } });
s.furnish("curtains", { room: "f_master", against: "front", along_ft: 5.0, size: { w_ft: 7.2 }, color: "#efe9df" });
s.furnish("ceiling_fan", { room: "f_master", at: [5.0, 7.0] });
s.furnish("ac_split", { room: "f_master", against: "left", along_ft: 7.2 });

// Master bathroom (6 x 9 ft): vanity, WC and glass shower enclosure.
s.furnish("vanity", { room: "f_master_bath", against: "front", along_ft: 3.0, size: { w_ft: 3.2 } });
