s.furnish("towel_rail", { room: "f_master_bath", against: "left", along_ft: 6.5 });

// Front granite-framed balcony (16 x 4 ft): outdoor lounge chairs and potted plant on the right.
s.furnish("outdoor_chair", { room: "f_balcony", at: [11.5, 2.0], rot_deg: -60 });
s.furnish("outdoor_table", { room: "f_balcony", at: [13.2, 2.0] });
s.furnish("plant_floor", { room: "f_balcony", at: [14.8, 1.8] });

// Bedroom 2 (9 x 13 ft) at front-left behind the timber louvers: queen bed on the right wall,
