s.furnish("bed_queen", { room: "f_bed2", against: "right", along_ft: 6.5, color: "#d4cbbd", variant: "upholstered headboard" });
s.furnish("side_table", { room: "f_bed2", against: "right", along_ft: 2.8 });
s.furnish("side_table", { room: "f_bed2", against: "right", along_ft: 10.2 });
