s.furnish("ac_split", { room: "f_bed2", against: "right", along_ft: 6.5 });

// Dressing 2 (5 x 10 ft): full wardrobe along the left wall and dressing mirror at the back.
s.furnish("wardrobe", { room: "f_bed2_dress", against: "left", along_ft: 5.0, size: { w_ft: 6.0, d_ft: 1.8 } });
