s.furnish("tv_unit", { room: "f_lounge", against: "front", along_ft: 14.5, size: { w_ft: 5.5, d_ft: 1.4 } });
s.furnish("tv", { room: "f_lounge", against: "front", along_ft: 14.5, size: { w_ft: 4.2 } });
